    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint val) public payable {
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint afterVal = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(!reverted && afterVal == val);
    }
}

